--- index.html
+++ index.html
@@ -17,4 +17,43 @@
 <div class="overlay" id="overlay"><section class="card"><div class="eyebrow" id="eyebrow">A LITTLE ADVENTURE AWAITS</div><h1 id="title">The Sunstone<br>Run</h1><p id="message">Leap through the wilds, gather glowing sunstones, and find the temple gate. A brave guardian’s journey begins here.</p><button class="primary" id="startBtn">START ADVENTURE&nbsp; →</button><p class="fineprint">Move with ← → or A / D · Jump with SPACE / ↑<br>On touchscreens, use the on-screen controls.</p></section></div>
 <div class="touch-controls" aria-label="Touch controls"><div class="pad"><button class="control" data-control="left" aria-label="Move left">←</button><button class="control" data-control="right" aria-label="Move right">→</button></div><button class="control jump" data-control="jump" aria-label="Jump">JUMP</button></div>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),shell=document.querySelector('.shell');
+const W=960,H=540,levelW=3600,groundY=454;
+let scaleX=1,scaleY=1,cam=0,last=0,playing=false,won=false,coins=0,lives=3,toastTimer=0,soundOn=false,audioCtx=null;
+const keys={left:false,right:false,jump:false};
+const player={x:70,y:300,w:34,h:49,vx:0,vy:0,ground:false,facing:1,invuln:0,anim:0,checkpoint:70};
+const platforms=[
+{x:0,y:groundY,w:460},{x:520,y:groundY,w:370},{x:960,y:groundY,w:460},{x:1490,y:groundY,w:420},{x:1980,y:groundY,w:430},{x:2490,y:groundY,w:420},{x:3000,y:groundY,w:600},
+{x:200,y:365,w:120},{x:385,y:300,w:120},{x:585,y:366,w:130},{x:760,y:302,w:115},{x:1040,y:360,w:140},{x:1240,y:295,w:130},{x:1550,y:360,w:130},{x:1740,y:295,w:140},{x:2035,y:360,w:135},{x:2240,y:290,w:130},{x:2550,y:360,w:130},{x:2745,y:295,w:125},{x:3100,y:360,w:150},{x:3335,y:300,w:140}
+];
+const gems=[...Array(27)].map((_,i)=>({x:180+i*125+(i%3)*15,y:[405,324,258,330,405,318][i%6],got:false,bob:Math.random()*6}));
+const enemies=[{x:660,y:420,vx:48,min:590,max:845,alive:true},{x:1130,y:420,vx:55,min:980,max:1380,alive:true},{x:1690,y:420,vx:54,min:1520,max:1880,alive:true},{x:2180,y:420,vx:58,min:2010,max:2390,alive:true},{x:2680,y:420,vx:55,min:2520,max:2890,alive:true},{x:3200,y:420,vx:60,min:3030,max:3520,alive:true}];
+const particles=[];
+function resize(){const r=shell.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);scaleX=canvas.width/W;scaleY=canvas.height/H;ctx.setTransform(scaleX,0,0,scaleY,0,0)}
+new ResizeObserver(resize).observe(shell);resize();
+function platformAt(x,y,w,h){return platforms.find(p=>x+w>p.x&&x<p.x+p.w&&y+h>=p.y&&y+h<=p.y+18)}
+function tone(freq=700,dur=.08,type='sine'){if(!soundOn)return;try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
+function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=1.5}
+function start(){if(won){reset()}playing=true;document.getElementById('overlay').classList.add('hidden');document.getElementById('help').style.opacity='.86';last=performance.now()}
+function reset(){coins=0;lives=3;won=false;player.x=70;player.y=300;player.vx=player.vy=0;player.checkpoint=70;gems.forEach(g=>g.got=false);enemies.forEach(e=>e.alive=true);updateUI()}
+function updateUI(){document.getElementById('coinCount').textContent=String(coins).padStart(2,'0');document.getElementById('lifeCount').textContent=lives}
+document.getElementById('startBtn').addEventListener('click',start);
+document.getElementById('soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';if(soundOn)tone(650,.12)});
+window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp',' ','a','d','w','A','D','W'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=true;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=true;if(e.key==='ArrowUp'||e.key===' '||e.key==='w'||e.key==='W'){if(!keys.jump)jump();keys.jump=true}if((e.key==='Enter'||e.key===' ')&&!playing)start()},{passive:false});
+window.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=false;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=false;if(e.key==='ArrowUp'||e.key===' '||e.key==='w'||e.key==='W')keys.jump=false});
+document.querySelectorAll('.control').forEach(b=>{const key=b.dataset.control;const down=e=>{e.preventDefault();b.classList.add('pressed');if(key==='jump'){if(!keys.jump)jump();keys.jump=true}else keys[key]=true};const up=e=>{e.preventDefault();b.classList.remove('pressed');if(key==='jump')keys.jump=false;else keys[key]=false};b.addEventListener('pointerdown',down);['pointerup','pointercancel','lostpointercapture'].forEach(n=>b.addEventListener(n,up));b.addEventListener('contextmenu',e=>e.preventDefault())});
+function jump(){if(playing&&player.ground){player.vy=-590;player.ground=false;tone(340,.11,'triangle')}}
+function hurt(){if(player.invuln>0)return;lives--;player.invuln=1.5;player.vy=-330;player.vx=-player.facing*180;tone(150,.22,'sawtooth');updateUI();if(lives<=0){playing=false;document.getElementById('eyebrow').textContent='THE WILD IS FULL OF SURPRISES';document.getElementById('title').innerHTML='Try Again';document.getElementById('message').textContent='Every brave adventurer stumbles. Your sunstones are safe — give it another go!';document.getElementById('startBtn').textContent='PLAY AGAIN  →';document.getElementById('overlay').classList.remove('hidden')}}
+function update(dt){if(!playing)return;player.anim+=dt*12;if(player.invuln>0)player.invuln-=dt;if(toastTimer>0&&(toastTimer-=dt)<=0)document.getElementById('toast').classList.remove('show');
+const accel=keys.left===keys.right?0:(keys.left?-1:1);if(accel){player.vx+=accel*1750*dt;player.vx=Math.max(-260,Math.min(260,player.vx));player.facing=accel}else player.vx*=Math.pow(.001,dt);let oldY=player.y;player.x=Math.max(0,Math.min(levelW-player.w,player.x+player.vx*dt));player.y+=player.vy*dt;player.vy=Math.min(900,player.vy+1500*dt);player.ground=false;
+for(const p of platforms){if(player.x+player.w>p.x&&player.x<p.x+p.w&&oldY+player.h<=p.y+5&&player.y+player.h>=p.y&&player.vy>=0){player.y=p.y-player.h;player.vy=0;player.ground=true}}
+if(player.y>H+200){hurt();player.x=player.checkpoint;player.y=220;player.vy=0}
+for(const g of gems){if(g.got)continue;const gy=g.y+Math.sin(performance.now()/280+g.bob)*5;if(player.x<g.x+14&&player.x+player.w>g.x-14&&player.y<gy+14&&player.y+player.h>gy-14){g.got=true;coins++;tone(840,.1,'sine');updateUI();showToast('SUNSTONE  +1');for(let i=0;i<8;i++)particles.push({x:g.x,y:gy,vx:(Math.random()-.5)*140,vy:(Math.random()-.7)*140,life:.5,color:'#ffdb75'})}}
+for(const e of enemies){if(!e.alive)continue;e.x+=e.vx*dt;if(e.x<e.min||e.x>e.max)e.vx*=-1;if(player.x+player.w>e.x&&player.x<e.x+35&&player.y+player.h>e.y+4&&player.y<e.y+34){if(player.vy>100&&player.y+player.h<e.y+26){e.alive=false;player.vy=-370;tone(250,.13,'square');for(let i=0;i<10;i++)particles.push({x:e.x+16,y:e.y+10,vx:(Math.random()-.5)*180,vy:-Math.random()*160,life:.55,color:'#d88a59'})}else hurt()}}
+if(player.x>1450&&player.checkpoint<1400){player.checkpoint=1510;showToast('CAMPFIRE CHECKPOINT');tone(590,.18)}
+if(player.x>levelW-125){won=true;playing=false;document.getElementById('eyebrow').textContent='THE TEMPLE GATE IS OPEN';document.getElementById('title').innerHTML='Sunstone<br>Champion!';document.getElementById('message').textContent=`You crossed the wilds and gathered ${coins} sunstone${coins===1?'':'s'} — a legend in the making.`;document.getElementById('startBtn').textContent='PLAY AGAIN  →';document.getElementById('overlay').classList.remove('hidden');tone(760,.3);setTimeout(()=>tone(980,.35),140)}
+for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
+cam=Math.max(0,Math.min(levelW-W,player.x-W*.36));
+}

