function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawSky(){const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#86c7d0');grad.addColorStop(.58,'#f3c997');grad.addColorStop(1,'#e88d65');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
const sun=ctx.createRadialGradient(765,150,8,765,150,104);sun.addColorStop(0,'#fff4cd');sun.addColorStop(.18,'#ffe7aa');sun.addColorStop(1,'#ffe7aa00');ctx.fillStyle=sun;ctx.fillRect(650,40,230,220);ctx.fillStyle='#ffe5a7';ctx.beginPath();ctx.arc(765,150,38,0,7);ctx.fill();
for(let i=0;i<8;i++){const x=((i*189-cam*.14)%(W+200)+W+200)%(W+200)-80,y=70+(i%3)*48;ctx.fillStyle='#fff3d2';ctx.globalAlpha=.22;ctx.beginPath();ctx.ellipse(x,y,36,9,0,0,7);ctx.ellipse(x+25,y-6,26,12,0,0,7);ctx.ellipse(x+50,y,32,8,0,0,7);ctx.fill();ctx.globalAlpha=1}
for(let layer=0;layer<3;layer++){const off=cam*[.12,.21,.33][layer];ctx.beginPath();ctx.moveTo(0,H);let x=-240-(off%240);for(;x<W+300;x+=240){const peak=230+layer*52+Math.sin((x+off)*.009)*25;ctx.lineTo(x,peak);ctx.lineTo(x+115,peak-95+layer*18);ctx.lineTo(x+240,peak+12)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#a2b9ae','#728d84','#526d66'][layer];ctx.fill();if(layer===0){ctx.fillStyle='#f8e6c6';for(let j=0;j<12;j++){let sx=(j*165-off*.8+W*3)%(W+200)-50;ctx.beginPath();ctx.moveTo(sx,166+(j%3)*18);ctx.lineTo(sx+24,185+(j%3)*18);ctx.lineTo(sx+40,171+(j%3)*18);ctx.closePath();ctx.fill()}}}
// distant amber canopy
ctx.fillStyle='#55776c';for(let i=0;i<16;i++){const x=((i*110-cam*.43)%(W+150)+W+150)%(W+150)-60;const y=365+(i%3)*9;ctx.beginPath();ctx.arc(x,y,32+(i%4)*4,Math.PI,0);ctx.fill()}}
function drawPlatform(p){const x=p.x-cam;if(x+p.w<0||x>W)return;ctx.fillStyle='#273e3c';ctx.fillRect(x,p.y,p.w,18);ctx.fillStyle='#68895e';ctx.fillRect(x,p.y,p.w,8);ctx.fillStyle='#9caa6a';for(let i=0;i<p.w;i+=24){ctx.fillRect(x+i+4,p.y-2,8,3)}ctx.fillStyle='#704f43';ctx.fillRect(x,p.y+18,p.w,10);ctx.fillStyle='#8c5c45';for(let i=12;i<p.w;i+=34){ctx.fillRect(x+i,p.y+21,13,4);ctx.fillStyle='#a4704f';ctx.fillRect(x+i+15,p.y+26,6,3);ctx.fillStyle='#8c5c45'} }
function drawTree(x,y,s=1){x-=cam;if(x<-80||x>W+80)return;ctx.fillStyle='#564334';ctx.fillRect(x-7*s,y-70*s,14*s,70*s);ctx.fillStyle='#405c4c';ctx.beginPath();ctx.arc(x,y-78*s,29*s,0,7);ctx.arc(x-20*s,y-57*s,23*s,0,7);ctx.arc(x+19*s,y-58*s,22*s,0,7);ctx.fill();ctx.fillStyle='#71835b';ctx.beginPath();ctx.arc(x-10*s,y-91*s,9*s,0,7);ctx.arc(x+15*s,y-69*s,7*s,0,7);ctx.fill()}
function drawWorld(){drawSky();for(let x=95;x<levelW;x+=245)drawTree(x,groundY,[.7,.9,1.08][Math.floor(x/245)%3]);
// land base
ctx.fillStyle='#293b35';ctx.fillRect(-cam,groundY,levelW,H-groundY);ctx.fillStyle='#77905a';ctx.fillRect(-cam,groundY,levelW,11);ctx.fillStyle='#a5a66c';for(let x=0;x<levelW;x+=27){ctx.fillRect(x-cam+4,groundY+3,8,3);ctx.fillStyle='#55463e';ctx.fillRect(x-cam+10,groundY+28,12,5);ctx.fillStyle='#a5a66c'}
for(const p of platforms)if(p.y<groundY)drawPlatform(p);for(const p of platforms)if(p.y===groundY&&p.x%500!==0)drawPlatform(p);
// tiny grass tufts
ctx.fillStyle='#a8a974';for(let x=110;x<levelW;x+=107){const sx=x-cam;if(sx>-20&&sx<W+20){ctx.beginPath();ctx.moveTo(sx,groundY);ctx.lineTo(sx-4,groundY-8);ctx.lineTo(sx+2,groundY);ctx.lineTo(sx+8,groundY-6);ctx.lineTo(sx+7,groundY);ctx.fill()}}
// checkpoint fire
if(player.checkpoint>1000){const bx=1518-cam;ctx.fillStyle='#7d5842';ctx.fillRect(bx-14,groundY-3,28,5);ctx.fillStyle='#f7954b';ctx.beginPath();ctx.moveTo(bx,groundY-5);ctx.quadraticCurveTo(bx-17,groundY-25,bx,groundY-40);ctx.quadraticCurveTo(bx+19,groundY-21,bx,groundY-5);ctx.fill();ctx.fillStyle='#ffe49c';ctx.beginPath();ctx.ellipse(bx,groundY-14,5,11,0,0,7);ctx.fill()}
for(const g of gems){if(g.got)continue;const gy=g.y+Math.sin(performance.now()/280+g.bob)*5,x=g.x-cam;if(x<-25||x>W+25)continue;ctx.fillStyle='#ffd55d';ctx.beginPath();ctx.arc(x,gy,11,0,7);ctx.fill();ctx.fillStyle='#fff2bd';ctx.beginPath();ctx.arc(x-3,gy-3,3,0,7);ctx.fill();ctx.fillStyle='#d9993e';ctx.beginPath();ctx.arc(x,gy,11,0,7);ctx.stroke()}
